        <?php foreach ($logs as $log): $auditRow=['action'=>$log['action'],'date'=>$log['created_at'],'acteur'=>$log['acteur_nom'],'role'=>$log['acteur_role'] ? libelleRole($log['acteur_role']) : 'Non identifié','departement'=>$log['acteur_service'],'ip'=>$log['ip_address'],'module'=>AuditLog::modules()[$log['module']],'dossier'=>($log['table_name'] ?? '—').($log['record_id'] ? ' #'.$log['record_id'] : ''),'contexte'=>$log['contexte'],'details'=>$log['detail_texte'],'lien'=>AuditLog::lien($log)]; ?><tr><td class="text-nowrap"><div><?= e(date('d/m/Y',strtotime($log['created_at']))) ?></div><div class="small text-muted"><?= e(date('H:i:s',strtotime($log['created_at']))) ?> · #<?= (int)$log['id'] ?></div></td><td><div class="fw-semibold"><?= e($log['acteur_nom']) ?></div><div class="small text-muted"><?= e($log['acteur_role'] ? libelleRole($log['acteur_role']) : 'Non identifié') ?><?= $log['acteur_service'] ? ' · '.e($log['acteur_service']) : '' ?></div></td><td><span class="badge bg-light text-dark border"><?= e(AuditLog::modules()[$log['module']]) ?></span></td><td style="min-width:230px;max-width:420px;white-space:normal;overflow-wrap:anywhere"><div><?= e($log['action']) ?></div><span class="small <?= $log['type']==='echec'?'text-danger':'text-muted' ?>"><?= e(AuditLog::types()[$log['type']]) ?></span></td><td><div class="small"><?= e($log['table_name'] ?? '—') ?></div><?php if ($log['record_id']): ?><div class="fw-semibold">#<?= (int)$log['record_id'] ?></div><?php endif; ?></td><td class="small text-nowrap"><?= e($log['ip_address'] ?: '—') ?></td><td class="text-end"><button type="button" class="btn btn-sm btn-outline-primary" data-audit-id="<?= (int)$log['id'] ?>" data-audit-row="<?= e(json_encode($auditRow,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE)) ?>" data-bs-toggle="modal" data-bs-target="#auditDetailModal" aria-label="Détail de l’événement <?= (int)$log['id'] ?>"><i class="bi bi-eye"></i></button></td></tr><?php endforeach; ?>
