<div class="modal fade" id="auditDetailModal" tabindex="-1" aria-labelledby="auditDetailTitle" aria-hidden="true"><div class="modal-dialog modal-lg modal-dialog-centered modal-dialog-scrollable"><div class="modal-content"><div class="modal-header"><h2 class="modal-title fs-5" id="auditDetailTitle">Détail de l’événement</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Fermer"></button></div><div class="modal-body p-4"><p id="auditDetailAction" class="fw-semibold"></p><dl class="row small" id="auditDetailMeta"></dl><h3 class="h6">Informations complémentaires</h3><pre id="auditDetailText" class="border rounded bg-light p-3 small mb-0" style="white-space:pre-wrap;overflow-wrap:anywhere"></pre></div><div class="modal-footer"><a id="auditDetailLink" class="btn btn-outline-primary" hidden>Ouvrir le dossier</a><button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Fermer</button></div></div></div></div>
<script>
(function(){document.getElementById('auditDetailModal').addEventListener('show.bs.modal',event=>{const button=event.relatedTarget,id=button?.dataset.auditId;if(!button?.dataset.auditRow)return;const row=JSON.parse(button.dataset.auditRow);document.getElementById('auditDetailTitle').textContent='Événement #'+id;document.getElementById('auditDetailAction').textContent=row.action;const list=document.getElementById('auditDetailMeta');list.replaceChildren();const meta={'Date / heure':row.date,'Utilisateur':row.acteur,'Rôle':row.role,'Département':row.departement,'Module':row.module,'Dossier':row.dossier,'Adresse IP':row.ip,'Méthode':row.contexte.methode,'Route':row.contexte.route};Object.entries(meta).forEach(([label,value])=>{if(value===null||value===undefined||value==='')return;const dt=document.createElement('dt'),dd=document.createElement('dd');dt.className='col-sm-4 text-muted fw-normal';dd.className='col-sm-8';dt.textContent=label;dd.textContent=value;list.append(dt,dd);});document.getElementById('auditDetailText').textContent=row.details||'Aucun détail complémentaire enregistré.';const link=document.getElementById('auditDetailLink');link.hidden=!row.lien;if(row.lien)link.href=row.lien;else link.removeAttribute('href');});})();
</script>
